/* ==UserStyle==
@name           meta.ai_css
@namespace      github.com/openstyles/stylus
@version        2026-08-19
@description    Meta AI Glassmorphic & Transparent Theme
@author         strmdn
==/UserStyle== */

@-moz-document domain("meta.ai"), domain("www.meta.ai") {
  /* === 1. 背景画像の設定 (URLを実際の画像URLに書き換えてください) === */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -2;
    background-image: url(data:image/jpeg;base64, ); background-size: cover;
    background-position: center;
    background-attachment: fixed;
  }

  /* === 2. アプリ全体の背景色を透明化 === */
  html, body, #root, main,
  div[data-slot="sidebar-wrapper"],
  div[data-slot="flexbox"],
  .bg-bg-primary,
  .bg-fill-blur-thick,
  .bg-fill-secondary {
    background: transparent !important;
    background-color: transparent !important;
  }

  /* === 3. メッセージ表示エリア（ガラス風にして透けさせる） === */
  /* アシスタント（Meta AI）のメッセージ */
  [data-testid="assistant-message"],
  div[data-message-item="true"] {
    background: rgba(255, 255, 255, 0.45) !important;
    backdrop-filter: blur(12px) saturate(1.2) !important;
    -webkit-backdrop-filter: blur(12px) saturate(1.2) !important;
    border-radius: 16px !important;
    border: 1px solid rgba(255, 255, 255, 0.3) !important;
    padding: 12px 16px !important;
  }

  /* ユーザー側の吹き出し */
  div[data-message-type="user"] .bg-fill-secondary {
    background: linear-gradient(135deg, rgba(255, 106, 213, 0.8), rgba(138, 92, 255, 0.8)) !important;
    backdrop-filter: blur(8px) !important;
    color: #fff !important;
  }

  /* 入力欄（フッター）のガラス化 */
  div[class*="backdrop-blur"] {
    background: rgba(255, 255, 255, 0.5) !important;
    backdrop-filter: blur(16px) !important;
    border: 1px solid rgba(255, 255, 255, 0.4) !important;
  }
}